1	package main
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7	)
8	
9	// These tests pin the queryTransforms "copy" rule at the boundary a user
10	// actually uses: the copy rule is read from the config file, one JSON request
11	// arrives on stdin, and routeId plus upstreamURL show the copied query. They
12	// never open a network connection and do not need the upstreams to exist, so
13	// they reproduce deterministically offline.
14	
15	// TestResolveCLICopyQueryTransform drives the headline copy behavior end to
16	// end. Copying "old" to "new" keeps every same-named source where it is and
17	// inserts each copy right after its source; the pre-existing new=9 stays in
18	// place (no merge, no overwrite); sources match by decoded name ("%6Fld")
19	// while their raw name spelling is left untouched; an empty value keeps its
20	// '=' and a parameter without '=' stays valueless in the copy. The success
21	// contract is the whole command's: exit 0, exactly one result JSON on stdout,
22	// empty stderr and raw '&' in upstreamURL (never a & escape).
23	func TestResolveCLICopyQueryTransform(t *testing.T) {
24		config := `{
25		  "routes": [
26		    {"id": "orders", "methods": ["GET"], "pathPrefix": "/api/orders",
27		     "upstream": "http://orders.internal",
28		     "queryTransforms": [{"op": "copy", "name": "old", "to": "new"}]}
29		  ]
30		}`
31		request := `{"method":"GET","target":"/api/orders/7?old=%2f+&new=9&%6Fld=&old"}`
32	
33		res := runResolveCLI(t, config, request)
34		success := assertResolveSuccess(t, res)
35		if success.RouteID != "orders" {
36			t.Errorf("routeId = %q, want orders", success.RouteID)
37		}
38		wantURL := "http://orders.internal/7?old=%2f+&new=%2f+&new=9&%6Fld=&new=&old&new"
39		if success.UpstreamURL != wantURL {
40			t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, wantURL)
41		}
42		// The copied query carries raw '&' separators, emitted literally rather
43		// than as a JSON unicode escape, and stdout is just the one result object.
44		if !bytes.Contains(res.stdout, []byte("&")) {
45			t.Errorf("stdout should contain raw '&': %s", res.stdout)
46		}
47		if bytes.Contains(res.stdout, []byte("\\u0026")) {
48			t.Errorf("stdout must not unicode-escape '&': %s", res.stdout)
49		}
50	}
51	
52	// TestResolveCLICopyBytesAndOrder covers the byte-level rules at the boundary:
53	// values (percent-escape case, '+', extra '=') are copied byte for byte, the
54	// empty-value and valueless forms stay distinct, sources match by decoded
55	// name without being re-encoded, unrelated parameters and empty fragments keep
56	// their bytes and order, no query string is created and an empty question mark
57	// survives, and copying a name onto itself neither duplicates nor re-encodes.
58	func TestResolveCLICopyBytesAndOrder(t *testing.T) {
59		rootCopyConfig := func(rule string) string {
60			return `{"routes":[{"id":"root","methods":["*"],"pathPrefix":"/",` +
61				`"upstream":"http://h.internal/base","queryTransforms":[` + rule + `]}]}`
62		}
63		copyOldToNew := `{"op":"copy","name":"old","to":"new"}`
64		cases := []struct {
65			name    string
66			rule    string
67			target  string
68			wantURL string
69		}{
70			{
71				name:    "value bytes are copied verbatim including escape case plus and extra equals",
72				rule:    copyOldToNew,
73				target:  "/p?old=%2f+%2F+a=b&x",
74				wantURL: "http://h.internal/base/p?old=%2f+%2F+a=b&new=%2f+%2F+a=b&x",
75			},
76			{
77				name:    "empty value keeps equals while a valueless parameter stays valueless",
78				rule:    copyOldToNew,
79				target:  "/p?old=&new=9&old",
80				wantURL: "http://h.internal/base/p?old=&new=&new=9&old&new",
81			},
82			{
83				name:    "source matches by decoded name but keeps its raw percent encoded spelling",
84				rule:    copyOldToNew,
85				target:  "/p?%6Fld=1&keep=2",
86				wantURL: "http://h.internal/base/p?%6Fld=1&new=1&keep=2",
87			},
88			{
89				name:    "unrelated parameters and empty fragments keep content and order",
90				rule:    copyOldToNew,
91				target:  "/p?a=1&&old=2&&",
92				wantURL: "http://h.internal/base/p?a=1&&old=2&new=2&&",
