			// parameters named "a" and "b", never one parameter whose name
			// contains '&', so a rule naming "a&b" cannot match.
			name:      "a raw separator never becomes part of a name",
			rules:     `[{"op":"copy","name":"a&b","to":"c"}]`,
			target:    "/p?a=1&b=2",
			wantQuery: "?a=1&b=2",
		},
